import React, { useState } from 'react';
import { View, Text, TextInput, Button, FlatList } from 'react-native';

const DreamJournalApp = () => {
  const [dreams, setDreams] = useState([]);
  const [newDream, setNewDream] = useState('');

  const addDream = () => {
    const newDreams = [...dreams, { id: Date.now(), dream: newDream }];
    setDreams(newDreams);
    setNewDream('');
  };

  const deleteDream = (id) => {
    const newDreams = dreams.filter((dream) => dream.id !== id);
    setDreams(newDreams);
  };

  return (
    <View>
      <Text>Dream Journal</Text>
      <TextInput
        value={newDream}
        onChangeText={(text) => setNewDream(text)}
        placeholder="Enter your dream"
        style={{ height: 40, borderColor: 'gray', borderWidth: 1 }}
      />
      <Button title="Add Dream" onPress={addDream} />
      <FlatList
        data={dreams}
        renderItem={({ item }) => (
          <View>
            <Text>{item.dream}</Text>
            <Button title="Delete" onPress={() => deleteDream(item.id)} />
          </View>
        )}
        keyExtractor={(item) => item.id.toString()}
      />
    </View>
  );
};

export default DreamJournalApp;
