class My_Block extends WP_Block_Type {
  public function __construct() {
    parent::__construct(
      'my-block', // The name of the block
      array(
        'title' => 'My Block', // The title of the block
        'description' => 'A custom block with a heading, paragraph, and image.', // The description of the block
        'category' => 'common', // The category of the block
        'icon' => 'format-image', // The icon for the block
        'keywords' => array('heading', 'paragraph', 'image'), // The keywords for the block
      )
    );
  }

  // Define the render callback
  public function render_callback($attributes, $content) {
    $html = '<div class="my-block">';
    $html .= '<h2>' . $attributes['heading'] . '</h2>';
    $html .= '<p>' . $attributes['paragraph'] . '</p>';
    $html .= '<img src="' . $attributes['image'] . '" alt="' . $attributes['image'] . '">';
    $html .= '</div>';
    return $html;
  }
}

// Register the block type
